#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    if (n == 2) {
        printf("-1\n");
        return 0;
    }

    if (n == 1) {
        printf("1\n");
        return 0;
    }

    int offsets[40], count = 0;
    int m = n - 1;

    if (m % 2 == 0) {
        for (int k = 1; k <= m / 2; ++k) {
            offsets[count++] = -k;
            offsets[count++] = k;
        }
    } else {
        offsets[count++] = -1;
        offsets[count++] = -2;
        offsets[count++] = 3;

        int pairs = (m - 3) / 2;
        for (int k = 4; k < 4 + pairs; ++k) {
            offsets[count++] = -k;
            offsets[count++] = k;
        }
    }
    offsets[count++] = 0;

    int max_abs = 0;
    for (int i = 0; i < n; ++i) {
        int abs_value = abs(offsets[i]);
        if (abs_value > max_abs) max_abs = abs_value;
    }

    int center = max_abs + 1;
    int values[40];
    int min_value = 1000000, max_value = 0;

    for (int i = 0; i < n; ++i) {
        values[i] = offsets[i] + center;
        if (values[i] < min_value) min_value = values[i];
        if (values[i] > max_value) max_value = values[i];
    }

    int multiplier = max_value - min_value + 1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (j) printf(" ");
            printf("%d", multiplier * values[i] + values[j]);
        }
        printf("\n");
    }

    return 0;
}
